CREATE INDEX `idx_work_items_woken_repository_observation` ON `work_items` (`org_id`,`project_id`,`id`) WHERE json_extract(metadata, '$.repositoryObserver') = 1 AND json_extract(metadata, '$.observerWokenAt') IS NOT NULL AND json_extract(metadata, '$.report') IS NULL AND (disposition IN ('proposed','accepted') OR (disposition = 'cancelled' AND json_extract(metadata, '$.settleReason') = 'advisory push observation'));